// There are two kinds of variables in HCL:
//   * Input variables, sometimes simply called "variables"
//   * Local variables, also known as "locals"

type HclLocal struct {
	// Required. Name of the local variable.
	name string

	// Required. Value of the local variable.
	value any
}

func (l *HclLocal) TraverseRef(args ...string) hcl.Traversal {
	traverser := []string{"local"}

	if len(args) != 0 && strings.HasPrefix(args[0], "[") {
		// Traversal is accessing a list variable
		traverser = append(traverser, l.name+args[0])
		args = args[1:]
	} else {
		traverser = append(traverser, l.name)
	}

	traverser = append(traverser, args...)

	return CreateSimpleTraversal(traverser...)
}

func (l *HclLocal) ToBlock() (*hclwrite.Block, error) {
	if l.value == nil {
		return nil, errors.New("value must be supplied")
	}

	return HclCreateGenericBlock(
		"locals",
		[]string{},
		map[string]any{l.name: l.value},
	)
}

// NewLocal Create a local variable in HCL.
func NewLocal(name string, value any) *HclLocal {
	return &HclLocal{name: name, value: value}
}

// Variables are not used yet, but we might use them in the future and they
// would look something similar to this.
//
// type HclVariable struct { }

type ForEach struct {
	key   string
	value map[string]string
}

type HclOutput struct {
	// Required. Name of the resultant output.
	name string

	// Required. Converted into a traversal.
	// e.g. []string{"a", "b", "c"} as input results in traversal having value a.b.c
	value []string

	// Optional.
	description string
}

func (m *HclOutput) ToBlock() (*hclwrite.Block, error) {
	if m.value == nil {
		return nil, errors.New("value must be supplied")
	}

	attributes := map[string]any{
		"value": CreateSimpleTraversal(m.value...),
	}

	if m.description != "" {
		attributes["description"] = m.description
	}

	return HclCreateGenericBlock(
		"output",
		[]string{m.name},
		attributes,
	)
}

// NewOutput Create a provider statement in the HCL output.
func NewOutput(name string, value []string, description string) *HclOutput {
	return &HclOutput{name: name, description: description, value: value}
}

type HclModule struct {
	// Required. Module name.
	name string

	// Required. Source for this module.
	source string

	// Required. Version.
	version string

	// Optional. Extra properties for this module.
	// Can supply string, bool, int, or map[string]any as values
	attributes map[string]any

	// Optional. Provide a map of strings. Creates an instance of the module block for each item in the map, with the
	// map keys assigned to the key field.
	forEach *ForEach

	// Optional. Provider details to override defaults. These values must be supplied as strings, and raw values will be
	// accepted. Unfortunately map[string]hcl.Traversal is not a format that is supported by hclwrite.SetAttributeValue
	// today so we must work around it (https://github.com/hashicorp/hcl/issues/347).
	providerDetails map[string]string
