 56	func runUnixUpdate(hc *http.Client) error {
 57		log.Info().Str("script", unixUpdateScript).Msg("detected linux-based platform, download update script")
 58		scriptData, err := download(hc, unixUpdateScript)
 59		if err != nil {
 60			return err
 61		}
 62	
 63		// check if bash is available
 64		_, err = exec.LookPath("bash")
 65		if err != nil {
 66			return errors.New("bash is not available, cannot run update script")
 67		}
 68	
 69		file, err := os.CreateTemp("", "mondoo")
 70		if err != nil {
 71			return err
 72		}
 73		defer os.Remove(file.Name())
 74	
 75		_, err = file.Write(scriptData)
 76		if err != nil {
 77			return errors.Wrap(err, "could not write downloaded script")
 78		}
 79	
 80		log.Info().Str("script", file.Name()).Msg("script downloaded successfully")
 81	
 82		log.Info().Msg("run update script")
 83		cmd := exec.Command("bash", file.Name())
 84		return runCmd(cmd)
 85	}
