 87	func runWindowsUpdate(hc *http.Client) error {
 88		log.Info().Str("script", windowsUpdateScript).Msg("detected windows platform, download update script")
 89		scriptData, err := download(hc, windowsUpdateScript)
 90		if err != nil {
 91			return err
 92		}
 93	
 94		file, err := os.CreateTemp("", "mondoo*.ps1")
 95		if err != nil {
 96			return err
 97		}
 98		defer os.Remove(file.Name())
 99	
100		_, err = file.Write(scriptData)
101		if err != nil {
102			return errors.Wrap(err, "could not write downloaded script")
103		}
104		// we need to close the file, otherwise Powershell cannot read it
105		err = file.Close()
106		if err != nil {
107			return errors.Wrap(err, "could not close downloaded script")
108		}
109	
110		log.Info().Msg("run update script")
111		cmd := exec.Command("powershell", "-c", "Import-module '"+file.Name()+"';Install-Mondoo;")
112		return runCmd(cmd)
113	}
