102	// NewSqliteScanDataStoreReader creates a new SQLite-based scan data store for reading
103	func NewSqliteScanDataStoreReader(filePath string) (*SqliteScanDataStore, error) {
104		sqlDB, err := sql.Open("sqlite", filePath+"?mode=ro")
105		if err != nil {
106			return nil, fmt.Errorf("failed to open sqlite file: %w", err)
107		}
108	
109		queries := sqlc.New(sqlDB)
110	
111		return &SqliteScanDataStore{
112			sqlDB:    sqlDB,
113			queries:  queries,
114			filePath: filePath,
115			readOnly: true,
116		}, nil
117	}
