 37	func RenderReport(report *mvd.VulnReport, writer RowWriter, opts RowWriterOpts) error {
 38		if report == nil || len(report.Advisories) == 0 {
 39			return nil
 40		}
 41	
 42		defer writer.Flush()
 43	
 44		err := writer.WriteHeader()
 45		if err != nil {
 46			return err
 47		}
 48	
 49		rows := ReportAffectedPackages(report, opts)
 50		for i := range rows {
 51			err = writer.Write(*rows[i])
 52			if err != nil {
 53				return err
 54			}
 55		}
 56	
 57		return nil
 58	}
 59	
 60	func ReportAffectedPackages(report *mvd.VulnReport, opts RowWriterOpts) []*ReportFindingRow {
 61		rows := make([]*ReportFindingRow, 0)
 62		advisoriesByPackage := advisoriesByPackage(report.Advisories)
 63	
 64		// iterate over all affected packages, therefore we filter the package list by affected
 65		affectedPkgs := mvd.FilterByAffected(report.Packages)
 66		// sort packages by score
 67		if opts.ScoreAscending {
 68			sort.Sort(mvd.ByPkgSeverity(affectedPkgs))
 69		} else {
 70			sort.Sort(sort.Reverse(mvd.ByPkgSeverity(affectedPkgs)))
 71		}
 72	
 73		for i := range affectedPkgs {
 74			pkg := affectedPkgs[i]
 75	
 76			// iterate over each advisory per package
 77			id := pkgID(pkg)
 78	
 79			advisories := advisoriesByPackage[id].Advisories
 80			if opts.ScoreAscending {
 81				sort.Sort(mvd.BySeverity(advisories))
 82			} else {
 83				sort.Sort(sort.Reverse(mvd.BySeverity(advisories)))
 84			}
 85	
 86			if len(advisories) > 0 {
 87				pkgWithMaxFixed := advisoriesByPackage[id].Pkg
 88				row := ReportFindingRow{
 89					Score:     pkgWithMaxFixed.Score,
 90					Name:      pkgWithMaxFixed.Name,
 91					Installed: pkgWithMaxFixed.Version,
 92					Fixed:     filterZeroEpochPrefix(advisoriesByPackage[id].MaxVulnerable),
 93					Available: pkgWithMaxFixed.Available,
 94					Advisory:  "",
 95					Cves:      nil,
 96				}
 97				rows = append(rows, &row)
 98	
 99				if opts.AdvisoryDetails {
100					// iterate over all advisories and print details
101					for j := range advisories {
102						advisory := advisories[j]
103	
104						var vulnerableVersion string
105						vulnerable := findVulnerablePackageWithoutNamespace(advisory, pkg)
106						if vulnerable != nil {
107							vulnerableVersion = vulnerable.Version
108						}
109	
110						row := ReportFindingRow{
111							Score:     advisory.Score,
112							Name:      pkg.Name,
113							Installed: pkg.Version,
114							Fixed:     filterZeroEpochPrefix(vulnerableVersion),
115							Available: pkg.Available,
116							Advisory:  advisory.ID,
117							Cves:      cvesToString(advisory.Cves),
118						}
119	
120						rows = append(rows, &row)
121					}
122				}
123			} else {
124				log.Warn().Str("name", pkg.Name).Msg("pkg is missing advisory information, please contact support.")
125				row := ReportFindingRow{
126					Score:     0.0,
127					Name:      pkg.Name,
128					Installed: pkg.Version,
129					Fixed:     "",
130					Available: pkg.Available,
131					Advisory:  "",
132					Cves:      nil,
133				}
134	
135				rows = append(rows, &row)
136			}
137		}
138		return rows
139	}
