164	// AdvisoriesByPackage iterates over advisories and store all advisories per package
165	// The entry.Pkg.Fixed will state the latest version that fixes all advisories
166	func advisoriesByPackage(advisories []*mvd.Advisory) map[string]Entry {
167		advisoriesByPackage := map[string]Entry{}
168		for i := range advisories {
169			advisory := advisories[i]
170			// iterate over all affected packages per advisory
171			for j := range advisory.Affected {
172	
173				pkg := advisory.Affected[j]
174				fixed := findVulnerablePackageWithoutNamespace(advisory, pkg)
175	
176				maxVulnerable := ""
177				if fixed != nil {
178					maxVulnerable = fixed.Version
179				}
180	
181				pID := pkgID(pkg)
182				pkgEntry, ok := advisoriesByPackage[pID]
183				if !ok {
184					advisoriesByPackage[pID] = Entry{
185						Pkg:           pkg,
186						Advisories:    []*mvd.Advisory{advisory},
187						MaxVulnerable: maxVulnerable,
188					}
189				} else {
190					if fixed != nil {
191						// determine max version of required fix for advisory
192						cmp, err := generic.Compare(pkgEntry.Pkg.Format, pkgEntry.MaxVulnerable, maxVulnerable)
193						if err == nil && cmp < 0 {
194							pkgEntry.MaxVulnerable = maxVulnerable
195						}
196					}
197	
198					pkgEntry.Advisories = append(pkgEntry.Advisories, advisory)
199					advisoriesByPackage[pID] = pkgEntry
200				}

