 55	func (l *BundleLoader) getResolver(path string) (BundleResolver, error) {
 56		for _, resolver := range l.resolvers {
 57			if resolver.IsApplicable(path) {
 58				return resolver, nil
 59			}
 60		}
 61		return nil, fmt.Errorf("no resolver found for path '%s'", path)
